root_owned_changes_requested.change:
# Experimental capture-latency calibration record from an operator clip; analysis only, never adopts a default.
timing-calibration-analyze input segments distances method amp_chain setup_id output_root:
    timeout 600 python3 scripts/timing_calibration.py analyze {{quote(input)}} --segments {{quote(segments)}} --distances {{quote(distances)}} --distance-method {{quote(method)}} --amp-chain {{quote(amp_chain)}} --setup-id {{quote(setup_id)}} --output-root {{quote(output_root)}}

# Calibrated phrase-timing view: direction only beyond the calibrated uncertainty; the phrase-timing input is never modified.
timing-calibration-apply phrase_timing calibration setup_id output_root:
    timeout 600 python3 scripts/timing_calibration.py apply --phrase-timing {{quote(phrase_timing)}} --calibration {{quote(calibration)}} --setup-id {{quote(setup_id)}} --output-root {{quote(output_root)}}
